function runCounter(times) {
  function makeCounter() {
    let count = 0;
    return function () {
      count = count + 1;
      return count;
    };
  }

  const next = makeCounter();
  const results = [];
  for (let i = 0; i < times; i = i + 1) {
    results.push(next());
  }
  return results;
}

