  const base = String(cfg.baseUrl || "").replace(/\/+$/, "");
  const path = String(cfg.path || "");
  const tail = path === "" || path.startsWith("/") ? path : "/" + path;
  const headers = { Accept: "application/json" };
  if (typeof cfg.token === "string" && cfg.token !== "") {
    headers.Authorization = "Bearer " + cfg.token;
  }
  let body = null;
  if (cfg.body !== undefined && cfg.body !== null) {
    headers["Content-Type"] = "application/json";
    body = JSON.stringify(cfg.body);
  }
  return { method: String(cfg.method || "GET").toUpperCase(), url: base + tail,
           headers: headers, body: body };
}

function parseResponse(raw) {
  const res = raw || {};
  const status = res.status;
  let data = null;
  if (typeof res.body === "string" && res.body.trim() !== "") {
    try {
      data = JSON.parse(res.body);
    } catch (err) {
      return { ok: false, status: status, error: "Malformed response body" };
    }
  }
  if (status >= 200 && status < 300) return { ok: true, status: status, data: data };
  const message = data && typeof data.message === "string" ? data.message : "HTTP " + status;
  return { ok: false, status: status, error: message };
}

function shouldRetry(response, attempt) {
  if (attempt >= 3) return false;
  if (!response || response.ok) return false;
  return response.status === 429 || response.status >= 500;
}

function backoffDelay(attempt) {
  if (attempt < 1) return 0;
  return Math.min(100 * Math.pow(2, attempt - 1), 800);
}

async function runRequest(transport, config) {
  const request = buildRequest(config);
  const delays = [];
  let attempt = 1;
  for (;;) {
    const response = parseResponse(await transport(request));
    if (!shouldRetry(response, attempt)) {
      return Object.assign({}, response, { attempts: attempt, delays: delays });
    }
    delays.push(backoffDelay(attempt));
    attempt += 1;
  }
}
